#!/usr/bin/env python3
import base64, os, subprocess, time, signal, urllib.request

DIR = "/root/vitqa"
FILES = {
  "frontend/css/style.css": """""",
  "frontend/js/app.js": """""",
  "frontend/js/i18n.js": """""",
  "frontend/index.html": """"""
}

print("=== Writing files ===")
for p, b64 in FILES.items():
    full = os.path.join(DIR, p)
    os.makedirs(os.path.dirname(full), exist_ok=True)
    data = base64.b64decode(b64)
    with open(full, "wb") as f:
        f.write(data)
    print(f"  {p}: {len(data)} bytes")

print("=== Restarting vitqa ===")
for proc in subprocess.run(["ps", "aux"], capture_output=True, text=True).stdout.split(chr(10)):
    if "python run.py" in proc and "grep" not in proc:
        parts = proc.split()
        if len(parts) > 1:
            try:
                pid = int(parts[1])
                os.kill(pid, signal.SIGTERM)
                print(f"  Killed PID {pid}")
                time.sleep(2)
            except: pass

os.chdir(os.path.join(DIR, "backend"))
proc = subprocess.Popen(["python3", "run.py"], stdout=open("/tmp/vitqa.log","w"), stderr=subprocess.STDOUT)
print(f"  Started vitqa (PID {proc.pid})")
time.sleep(3)
try:
    r = urllib.request.urlopen("http://localhost:5005/api/health")
    print(f"  Health: {r.read().decode()}")
except: print("  Health check failed")
print("=== Done! ===")